#include <vector>
using namespace std;

int main() {
    int A, B;
    scanf("%d %d", &A, &B); // Combined input

    vector<int> P(A), Q(B);
    for (int i = 0; i < A + B; i++) {
        if (i < A) scanf("%d", &P[i]);
        else scanf("%d", &Q[i - A]);
    }

    int l = 1;
    int r = B;
    int m;

    while (r - l > 1) {
        m = (l + r) / 2;
        bool ok = false;

        for (int j = 0; j <= B - m; j++) {
            int ptr = j;
            for (int k = 0; k < A; k++) {
                if (P[k] == Q[ptr]) {
                    ptr++;
                }
                if (ptr == j + m) {
                    break;
                }
            }
            if (ptr == j + m) {
                ok = true;
                break; // Early exit if found
            }
        }

        if (ok) {
            l = m;
        } else {
            r = m;
        }
    }

    printf("%d\n", l);
    return 0;
}

